// Spike A alternative: a custom Worker entry that answers legacy redirects
// before Next.js runs, then delegates to the OpenNext handler.
// https://opennext.js.org/cloudflare/howtos/custom-worker
// Run with: pnpm build:cf && pnpm exec wrangler dev -c spikes/wrangler.custom-worker.jsonc
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

const REDIRECTS: Record<string, string> = {
  "/spike-cw/old-path/": "/spike-cw/new-path/",
  "/spike-cw/പരീക്ഷണം/": "/spike-cw/ml-target/",
};

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    const url = new URL(request.url);
    let path = url.pathname;
    try {
      path = decodeURIComponent(path);
    } catch {
      // keep raw path
    }
    const target = REDIRECTS[path];
    if (target) return Response.redirect(new URL(target, url).toString(), 301);
    if (path === "/spike-cw/d1-check/") {
      const row = await env.DB.prepare("SELECT count(*) AS n FROM user").first<{ n: number }>();
      return new Response(`custom worker D1 ok users=${row?.n}`);
    }
    return handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
